-- Taller SQL - Teoría de Bases de Datos (UMB)
-- 02_datos.sql : registros de datos, INSERT por INSERT (PostgreSQL)
-- 60 clientes, 60 productos, 250 pedidos, detalles, histórico y auditoría.
-- Ejecutar DESPUÉS de 01_ddl.sql
-- =====================================================================

BEGIN;

-- ---------- CATEGORIA ----------

-- ---------- CLIENTE ----------

-- ---------- PRODUCTO ----------

-- ---------- PEDIDO ----------

-- ---------- DETALLE_PEDIDO ----------

-- ---------- HISTORICO_PRECIOS ----------

-- ---------- AUDITORIA_PEDIDOS ----------

COMMIT;

-- ---------- Verificación ----------
SELECT (SELECT COUNT(*) FROM CLIENTE)           AS clientes,
       (SELECT COUNT(*) FROM PRODUCTO)          AS productos,
       (SELECT COUNT(*) FROM PEDIDO)            AS pedidos,
       (SELECT COUNT(*) FROM DETALLE_PEDIDO)    AS detalles,
       (SELECT COUNT(*) FROM HISTORICO_PRECIOS) AS historico,
       (SELECT COUNT(*) FROM AUDITORIA_PEDIDOS) AS auditoria;